export const designColors={original:null,cream:'#eee2ca',sage:'#9eae91',forest:'#526e5c',rose:'#bd9091',clay:'#b8896d',ocean:'#6d96a3',lavender:'#aba2be',walnut:'#8a705c'};
export const designFields={outfit:{primary:Object.keys(designColors),trim:Object.keys(designColors),motif:['none','flower','star','heart']},planet:{grass:['original','sage','forest'],water:['original','ocean','sage'],roof:Object.keys(designColors)},home:{wall:Object.keys(designColors),curtain:Object.keys(designColors),fabric:Object.keys(designColors),light:['original','warm','soft'],brightness:['normal','dim','bright']}};
export const defaultDesign=()=>({outfit:{primary:'original',trim:'original',motif:'none'},planet:{grass:'original',water:'original',roof:'original'},home:{wall:'original',curtain:'original',fabric:'original',light:'original',brightness:'normal'}});
export function validateDesignPart(scope,value){const fields=designFields[scope];if(!fields||!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length!==Object.keys(fields).length||Object.keys(value).some(k=>!Object.hasOwn(fields,k)))throw new Error('设计包含未开放的修改');for(const [k,allowed]of Object.entries(fields))if(!allowed.includes(value[k]))throw new Error('设计参数超出范围');return Object.fromEntries(Object.keys(fields).map(k=>[k,value[k]]))}
export function validateDesign(value){if(!value||Object.keys(value).length!==3)throw new Error('设计数据不完整');return Object.fromEntries(Object.keys(designFields).map(scope=>[scope,validateDesignPart(scope,value[scope])]))}
export const designExamples={outfit:{primary:'cream',trim:'forest',motif:'flower'},planet:{grass:'sage',water:'ocean',roof:'clay'},home:{wall:'cream',curtain:'sage',fabric:'rose',light:'warm',brightness:'normal'}};
export const designLabels={primary:'衣服',trim:'饰边',motif:'图案',grass:'草地',water:'水面',roof:'屋顶',wall:'墙面',curtain:'窗帘',fabric:'软装',light:'灯色',brightness:'亮度',original:'原样',cream:'奶油',sage:'鼠尾草',forest:'森林绿',rose:'玫瑰',clay:'陶土',ocean:'海蓝',lavender:'薰衣草',walnut:'胡桃',none:'无',flower:'小花',star:'星星',heart:'爱心',warm:'暖光',soft:'柔光',normal:'适中',dim:'柔和',bright:'明亮'};
